/**
 * Generate src/endpoints.generated.ts — the index of NON-ADMIN Magileads API
 * operations that the generic passthrough tools (magileads_get / magileads_request /
 * list_api_endpoints) are allowed to call.
 *
 * "Admin" tags (account/billing/reseller/team administration) are excluded so the
 * passthrough can't touch them. The Users tag is admin EXCEPT self reads under /users/me.
 *
 * Run:  bun run scripts/generate-endpoints.mjs   (fetches the live swagger)
 *   or  bun run scripts/generate-endpoints.mjs path/to/swagger.json
 *
 * The generated file is committed; re-run this only to refresh against a new swagger.
 */
import { writeFileSync, readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";

const SWAGGER_URL = "https://api.magileads.net/swagger.json";
const ADMIN_TAGS = new Set([
  "Resellers", "Organizations", "Teams", "Roles", "Permissions",
  "API Keys", "External API keys", "Subscriptions", "Crons", "Webhooks",
  "OVH", "Zapier", "Affiliation", "Pools", "Users",
]);
// Users is admin EXCEPT these self-service reads:
const USERS_ALLOW = (method, path) => method === "GET" && path.startsWith("/users/me");

async function loadSwagger() {
  const arg = process.argv[2];
  if (arg) return JSON.parse(readFileSync(arg, "utf8"));
  const res = await fetch(SWAGGER_URL);
  if (!res.ok) throw new Error(`fetch swagger failed: ${res.status}`);
  return res.json();
}

const swagger = await loadSwagger();
const paths = swagger.paths ?? {};
const list = [];
for (const [path, methods] of Object.entries(paths)) {
  for (const [m, spec] of Object.entries(methods)) {
    if (!["get", "post", "put", "delete", "patch"].includes(m)) continue;
    if (!spec || typeof spec !== "object") continue;
    const method = m.toUpperCase();
    const tag = (spec.tags && spec.tags[0]) || "(none)";
    const isAdmin = ADMIN_TAGS.has(tag) && !(tag === "Users" && USERS_ALLOW(method, path));
    if (isAdmin) continue;
    list.push({
      method,
      path,
      tag,
      summary: (spec.summary || "").slice(0, 140),
      write: method !== "GET",
    });
  }
}
list.sort((a, b) => (a.path === b.path ? a.method.localeCompare(b.method) : a.path.localeCompare(b.path)));

const header = `// AUTO-GENERATED by scripts/generate-endpoints.mjs — do not edit by hand.
// Source: ${SWAGGER_URL}
// Non-admin Magileads API operations the generic passthrough tools may call.
// ${list.length} operations (${list.filter((e) => !e.write).length} read, ${list.filter((e) => e.write).length} write).

export type EndpointDef = { method: string; path: string; tag: string; summary: string; write: boolean };

export const NON_ADMIN_ENDPOINTS: EndpointDef[] = ${JSON.stringify(list, null, 2)};
`;

const outDir = dirname(fileURLToPath(import.meta.url));
const outFile = join(outDir, "..", "src", "endpoints.generated.ts");
writeFileSync(outFile, header, "utf8");
console.error(
  `Wrote ${outFile}: ${list.length} non-admin ops ` +
    `(${list.filter((e) => !e.write).length} read, ${list.filter((e) => e.write).length} write).`,
);
